    25	    const childRefs = useRef<HTMLElementWithText[]>([]);
    26	    // eslint-disable-next-line react-compiler/react-compiler
    27	    const isEllipsisActive = !!containerRef.current?.offsetWidth && !!containerRef.current?.scrollWidth && containerRef.current.offsetWidth < containerRef.current.scrollWidth;
    28	
    29	    /**
    30	     * We may need to shift the Tooltip horizontally as some of the inline text wraps well with ellipsis,
    31	     * but their container node overflows the parent view which causes the tooltip to be misplaced.
    32	     *
    33	     * So we shift it by calculating it as follows:
    34	     * 1. We get the container layout and take the Child inline text node.
    35	     * 2. Now we get the tooltip original position.
    36	     * 3. If inline node's right edge is overflowing the container's right edge, we set the tooltip to the center
    37	     * of the distance between the left edge of the inline node and right edge of the container.
    38	     * @param index Used to get the Ref to the node at the current index
    39	     * @returns Distance to shift the tooltip horizontally
    40	     */
    41	    const getTooltipShiftX = useCallback((index: number) => {
    42	        // Only shift the tooltip in case the containerLayout or Refs to the text node are available
    43	        if (!containerRef.current || index < 0 || !childRefs.current.at(index)) {
    44	            return 0;
    45	        }
    46	        const {width: containerWidth, left: containerLeft} = containerRef.current.getBoundingClientRect();
    47	
    48	        // We have to return the value as Number so we can't use `measureWindow` which takes a callback
    49	        const {width: textNodeWidth, left: textNodeLeft} = childRefs.current.at(index)?.getBoundingClientRect() ?? {width: 0, left: 0};
    50	        const tooltipX = textNodeWidth / 2 + textNodeLeft;
    51	        const containerRight = containerWidth + containerLeft;
    52	        const textNodeRight = textNodeWidth + textNodeLeft;
    53	        const newToolX = textNodeLeft + (containerRight - textNodeLeft) / 2;
    54	
    55	        // When text right end is beyond the Container right end
    56	        return textNodeRight > containerRight ? -(tooltipX - newToolX) : 0;
    57	    }, []);
